function ObjectList({ type }: { type: string }) {
  const c = configs[type];
  const [params, setParams] = useSearchParams();
  const q = params.get("q") || "";
  const status = params.get("status") || "";
  const order = params.get("order") || "updated_desc";
  const requestKey = `${c.endpoint}\u0000${q}\u0000${status}\u0000${order}`;
  const [result, setResult] = useState<{
    key: string;
    items: BusinessObject[];
    truncated: boolean;
    order?: string;
  }>({ key: "", items: [], truncated: false });
  // Held against the requestKey it belongs to, exactly as `result` is: that way
  // changing a filter stops the old refusal from applying without anyone having
  // to clear it, and clearing it at the top of `load` instead would land one
  // frame late and flash the previous failure over the new request.
  const [failure, setFailure] = useState({ key: "", message: "" });
  const [modal, setModal] = useState(false);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [views, setViews] = useState<SavedView[]>([]);
  const [activeView, setActiveView] = useState("");
  const [viewModal, setViewModal] = useState(false);
  const [columnModal, setColumnModal] = useState(false);
  const [visibleColumns, setVisibleColumns] = useState(defaultObjectColumns);
  const [viewName, setViewName] = useState("");
  const [shareView, setShareView] = useState(false);
  const [canShareViews, setCanShareViews] = useState(false);
  const [viewError, setViewError] = useState("");
  const loadSequence = useRef(0);
  const viewContext = `object:${type}`;
  const load = useCallback(() => {
    const sequence = ++loadSequence.current;
    return api<{ items: BusinessObject[]; truncated?: boolean; order?: string }>(
      `${c.endpoint}?q=${encodeURIComponent(q)}&status=${status}&order=${order}`,
    )
      .then((response) => {
        if (sequence !== loadSequence.current) return;
        setResult({
          key: requestKey,
          items: response.items,
          truncated: Boolean(response.truncated),
          // Read optionally: a server that does not answer with an applied sort
          // leaves the screen exactly as it was.
          order: response.order,
        });
        // An answer supersedes whatever the last attempt was refused for. The
        // functional form leaves the state object untouched when there was no
        // failure, so a healthy load still renders exactly once.
        setFailure((current) => (current.message ? { key: "", message: "" } : current));
      })
      .catch((cause: unknown) => {
        // Without this branch the rejection went nowhere: `loading` is derived
        // from `result.key !== requestKey`, which a request that never answered
        // can never satisfy, so the screen claimed "불러오는 중" about a refusal it
        // was already holding and then guessed at the cause twelve seconds later
        // — "연결이 끊겼거나 서비스가 재시작 중일 수 있습니다" for a 403 the server
        // had explained in words. The same sequence guard as the branch above:
        // a refusal that arrives after the reader asked something else is not an
        // answer about the new question.
        if (sequence !== loadSequence.current) return;
        setFailure({
          key: requestKey,
          // Worded apart from the <Empty> title below on purpose, the way
          // WorkInbox words its fallback apart from its own: a rejection with
          // nothing to say still has to say something, and reusing the title
          // verbatim prints the same sentence to the reader twice.
          message:
            cause instanceof Error && cause.message
              ? cause.message
              : "목록을 조회하지 못했습니다",
        });
      });
  }, [c.endpoint, order, q, requestKey, status]);
  useEffect(() => {
    void load();
  }, [load]);
  useEffect(() => {
    api<{ items: Supplier[] }>("/api/v1/suppliers?limit=500")
      .then((x) => setSuppliers(x.items))
      .catch(() => {});
  }, []);
  const loadViews = useCallback(() => {
    return api<{ items: SavedView[]; canShare: boolean }>(
      `/api/v1/me/saved-views?context=${encodeURIComponent(viewContext)}`,
    )
      .then((response) => {
        setViews(response.items);
        setCanShareViews(response.canShare);
      })
      .catch(() => setViews([]));
  }, [viewContext]);
  useEffect(() => {
    void loadViews();
  }, [loadViews]);
  function set(key: string, v: string) {
    const n = new URLSearchParams(params);
    if (v) n.set(key, v);
    else n.delete(key);
    setActiveView("");
    setParams(n);
  }
  function applyView(id: string) {
    setActiveView(id);
    const selected = views.find((view) => view.id === id);
    if (!selected) {
      setParams({});
      setVisibleColumns(defaultObjectColumns);
      return;
    }
    const next = new URLSearchParams();
    for (const [key, value] of Object.entries(selected.filters)) {
      if (typeof value === "string" && value) next.set(key, value);
    }
    setVisibleColumns(selected.columns?.length ? selected.columns : defaultObjectColumns);
    setParams(next);
  }
  async function saveView(event: FormEvent) {
    event.preventDefault();
    setViewError("");
    try {
      await post("/api/v1/me/saved-views", {
        name: viewName,
        context: viewContext,
        filters: { q, status, order },
        columns: visibleColumns,
        shared: shareView,
      });
      setViewModal(false);
      setViewName("");
      setShareView(false);
      await loadViews();
    } catch (cause) {
      setViewError(cause instanceof Error ? cause.message : "보기를 저장하지 못했습니다");
    }
  }
  async function removeView() {
    const selected = views.find((view) => view.id === activeView);
    if (!selected?.owned) return;
    try {
      await del(`/api/v1/me/saved-views/${selected.id}`);
      setActiveView("");
      await loadViews();
    } catch (cause) {
      setViewError(cause instanceof Error ? cause.message : "보기를 삭제하지 못했습니다");
    }
  }
  const loading = result.key !== requestKey;
  const failed = failure.key === requestKey ? failure.message : "";
  const items = loading ? [] : result.items;
  const truncated = !loading && result.truncated;
  // Until the answer is in there is nothing to compare against, so the screen
  // keeps showing what was asked for rather than flickering a notice. An answer
  // without an order (an older server) or with one this dropdown cannot name is
  // the same case: say nothing and leave the control on the requested value,
  // because a value with no matching option would blank the dropdown instead.
  const answeredOrder = loading
    ? undefined
    : objectOrderOptions.find((option) => option.value === result.order);
  const appliedOrder = answeredOrder?.value ?? order;
  return (
    <div className="page">
      <PageHeader
        eyebrow={c.eyebrow}
        title={c.title}
        description={c.description}
        actions={
          <button className="button" onClick={() => setModal(true)}>
            <Plus />
            {c.create}
          </button>
        }
      />
      {truncated && (
        <p className="form-error warning list-truncated" role="status">
          <AlertCircle />
          결과가 많아 일부만 표시했습니다. 검색이나 필터로 범위를 좁히세요.
        </p>
      )}
      {answeredOrder && answeredOrder.value !== order && (
        <p className="form-error warning list-order-dropped" role="status">
          <AlertCircle />
          요청한 정렬을 적용할 수 없어 {answeredOrder.label}으로 표시했습니다.
          {order === "amount_desc" && " 금액을 볼 수 없는 목록은 금액순으로 정렬되지 않습니다."}
        </p>
      )}
      <div className="toolbar object-toolbar">
        <div className="search-box">
          <Search />
          <input
            value={q}
            onChange={(e) => set("q", e.target.value)}
            placeholder="번호 또는 제목 검색"
            aria-label="번호 또는 제목 검색"
          />
        </div>
        <select
          value={status}
          onChange={(e) => set("status", e.target.value)}
          aria-label="상태 필터"
        >
          <option value="">모든 상태</option>
          {objectStatusFilters.map((s) => (
            <option key={s.value} value={s.value}>
              {s.label}
            </option>
          ))}
        </select>
        {/* The URL stays the request and the dropdown shows what was applied, so
            picking a sort the server will not run snaps back with the notice
            above instead of leaving a sort selected that the rows are not in. */}
        <select
          value={appliedOrder}
          onChange={(event) => set("order", event.target.value)}
          aria-label="정렬 기준"
        >
          {objectOrderOptions.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
        <div className="saved-view-tools">
          <select
            value={activeView}
            onChange={(event) => applyView(event.target.value)}
            aria-label="저장된 보기"
          >
            <option value="">기본 보기</option>
            {views.map((view) => (
              <option value={view.id} key={view.id}>
                {view.shared ? "공유 · " : ""}{view.name}
              </option>
            ))}
          </select>
          <button className="button ghost" onClick={() => setViewModal(true)}>
            <BookmarkPlus />보기 저장
          </button>
          <button className="icon-button" onClick={() => setColumnModal(true)} title="표시 열 설정" aria-label="표시 열 설정">
            <Columns3 />
          </button>
          {views.find((view) => view.id === activeView)?.owned && (
            <button className="icon-button" onClick={() => void removeView()} title="현재 보기 삭제" aria-label="현재 보기 삭제">
              <Trash2 />
            </button>
          )}
        </div>
      </div>
      {viewError && !viewModal && <div className="form-error"><AlertCircle />{viewError}</div>}
      {/* Rows are already up and only the refresh was refused (onSaved, or a
          submit from the table): a failed refresh keeps the rows the reader is
          looking at — they are still the last thing the server actually said —
          and reports itself here in the same shape as viewError above. */}
      {!loading && failed && (
        <div className="form-error list-load-failed" role="status">
          <AlertCircle />
          {failed}
        </div>
      )}
      {loading && failed ? (
        <Empty
          title="목록을 불러오지 못했습니다"
          description={failed}
          action={
            <button className="button secondary" onClick={() => void load()}>
              <RefreshCw />
              다시 시도
            </button>
          }
        />
      ) : loading ? (
        <Loading />
      ) : (
        <ObjectTable
          items={items}
          empty={`${c.title} 데이터가 없습니다`}
          onSubmit={load}
          visibleColumns={visibleColumns}
        />
      )}{" "}
      {modal && (
        <NewObject
          config={c}
          type={type}
          suppliers={suppliers}
          onClose={() => setModal(false)}
          onSaved={() => {
            setModal(false);
            load();
          }}
        />
      )}
      {viewModal && (
        <Modal
          title="현재 보기를 저장"
          description="검색어와 상태 필터를 저장해 다시 사용하거나 같은 조직에 공유할 수 있습니다."
          onClose={() => setViewModal(false)}
        >
          <form onSubmit={saveView}>
            <Field label="보기 이름" required>
              <input autoFocus required maxLength={60} value={viewName} onChange={(event) => setViewName(event.target.value)} placeholder="예: 이번 달 만료 계약" />
            </Field>
            <div className="saved-view-preview">
              <Filter />
              <span><b>현재 조건</b><small>검색어 {q || "없음"} · 상태 {status || "전체"} · 표시 열 {visibleColumns.length + 1}개</small></span>
            </div>
            <label className="checkbox-line saved-view-share">
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import { describe, expect, it, vi } from "vitest";
import Objects from "./Objects";
import { api, APIError } from "../api";

vi.mock("../api", async (importOriginal) => ({
  ...(await importOriginal<typeof import("../api")>()),
  api: vi.fn(),
}));

const call = vi.mocked(api);

/**
 * Every work list in this product — 계약, 발주, 검수, Invoice, 지급 — renders this
 * one component, so a list request that is refused is refused on all of them at
 * once. The screen used to drop the rejection on the floor: `loading` is derived
 * from `result.key !== requestKey`, which a rejected request never satisfies, so
 * the spinner claimed "불러오는 중" for twelve seconds and then guessed at the
 * cause ("연결이 끊겼거나 서비스가 재시작 중일 수 있습니다") for a 403 the server
 * had already explained in words. These tests pin the screen to the server's own
 * reason and to a retry that re-sends the request rather than reloading the page.
 *
 * The list path is the only one that rejects: /api/v1/suppliers and
 * /api/v1/me/saved-views carry their own `.catch`, so they answer normally here.
 */
const refuse = (cause: unknown) => {
  call.mockImplementation(async (path: string) => {
    if (path.startsWith("/api/v1/suppliers")) return { items: [] } as never;
    if (path.startsWith("/api/v1/me/saved-views"))
      return { items: [], canShare: false } as never;
    throw cause;
  });
};

// Refuses the list until `heal()` is called, then answers it. The rejection is
// thrown inside the implementation rather than held in a variable, so no
// rejected promise is left floating for the runner to attribute to this file.
const refuseUntilHealed = (cause: unknown) => {
  let healed = false;
  call.mockImplementation(async (path: string) => {
    if (path.startsWith("/api/v1/suppliers")) return { items: [] } as never;
    if (path.startsWith("/api/v1/me/saved-views"))
      return { items: [], canShare: false } as never;
    if (!healed) throw cause;
    return { items: [], count: 0, limit: 100, truncated: false } as never;
  });
  return () => {
    healed = true;
  };
};

const show = (url: string) =>
  render(
    <MemoryRouter initialEntries={[url]}>
      <Objects type="contract" />
    </MemoryRouter>,
  );

const listCalls = () =>
  call.mock.calls.filter(([path]) => String(path).startsWith("/api/v1/contracts"));

describe("ObjectList 조회 실패", () => {
  // No beforeEach reset: vitest.config sets restoreMocks, and resetting a mock
  // that a previous test left a rejection in makes the runner report that
  // rejection against this file. Every test below waits for the screen to settle
  // so nothing is still in flight when it ends.

  it("shows the reason the server gave instead of a spinner", async () => {
    refuse(new APIError(403, "계약을 조회할 권한이 없습니다"));
    show("/contracts");

    await waitFor(() =>
      expect(
        screen.queryByText("계약을 조회할 권한이 없습니다"),
      ).toBeTruthy(),
    );
    expect(screen.queryByText("불러오는 중")).toBeNull();
  });

  it("retries the same request instead of reloading the page", async () => {
    const heal = refuseUntilHealed(new APIError(500, "요청 실패 (500)"));
    show("/contracts");

    await waitFor(() => expect(screen.queryByText("요청 실패 (500)")).toBeTruthy());
    const before = listCalls().length;

    heal();
    fireEvent.click(screen.getByRole("button", { name: /다시 시도/ }));

    await waitFor(() =>
      expect(screen.queryByText(/계약 데이터가 없습니다/)).toBeTruthy(),
    );
    expect(listCalls().length).toBe(before + 1);
  });

  it("drops the reason once a request succeeds", async () => {
    const heal = refuseUntilHealed(new APIError(500, "요청 실패 (500)"));
    show("/contracts");

    await waitFor(() => expect(screen.queryByText("요청 실패 (500)")).toBeTruthy());
    heal();
    fireEvent.click(screen.getByRole("button", { name: /다시 시도/ }));

    await waitFor(() =>
      expect(screen.queryByText(/계약 데이터가 없습니다/)).toBeTruthy(),
    );
    expect(document.body.textContent).not.toContain("요청 실패 (500)");
    expect(document.body.textContent).not.toContain("목록을 불러오지 못했습니다");
  });

  it("falls back to Korean when the rejection is not an Error", async () => {
    // A rejection that is not an Error, or an Error with an empty message, must
    // still end in words: an empty <Empty> description would say no more than
    // the spinner it replaced. The fallback is worded apart from the title so
    // the reader is not shown the same sentence twice.
    refuse("boom");
    show("/contracts");

    await waitFor(() =>
      expect(screen.queryByText("목록을 조회하지 못했습니다")).toBeTruthy(),
    );
    expect(screen.queryByText("불러오는 중")).toBeNull();
    expect(screen.queryByText("목록을 불러오지 못했습니다")).toBeTruthy();
  });

  it("falls back to Korean when the Error carries an empty message", async () => {
    refuse(new APIError(500, ""));
    show("/contracts");

    await waitFor(() =>
      expect(screen.queryByText("목록을 조회하지 못했습니다")).toBeTruthy(),
    );
    expect(screen.queryByText("불러오는 중")).toBeNull();
  });

  it("does not carry a stale failure onto the next filter", async () => {
    // The failure is stored against the requestKey it belongs to, so changing
    // the sort asks a new question and the old refusal stops applying to it
    // rather than hanging over the new request's spinner.
    const heal = refuseUntilHealed(new APIError(403, "계약을 조회할 권한이 없습니다"));
    show("/contracts?order=amount_desc");

    await waitFor(() =>
      expect(screen.queryByText("계약을 조회할 권한이 없습니다")).toBeTruthy(),
    );

    heal();
    fireEvent.change(screen.getByLabelText("정렬 기준"), {
      target: { value: "title_asc" },
    });

    await waitFor(() =>
      expect(screen.queryByText(/계약 데이터가 없습니다/)).toBeTruthy(),
    );
    expect(document.body.textContent).not.toContain("계약을 조회할 권한이 없습니다");
  });
});
# aidev 의 에이전트들 — 서로를 보완하는 구조

> 2026-09-19 부터 이 역할들은 회사 조직(headcount 부서)에 배속돼 부서 스킬을 싣고 돈다. 조직도·권한·차단 소견·이사회는 **[COMPANY.md](COMPANY.md)** 에.

한 세션이 파악·선택·구현·검증·기록을 다 하던 구조를, 역할이 다른 여러 세션이 서로의
산출물을 검사하는 구조로 바꿨다 (2026-09-18). 원칙은 셋이다.

1. **만드는 자와 검사하는 자를 분리한다.** 구현자는 자기 코드를 승인하지 못한다. 비평가는 코드를 고치지 못한다.
2. **읽기만 하는 자가 방향을 정한다.** 정찰은 커밋할 수 없으므로 "고치기 쉬운 것" 이 아니라 "고칠 가치가 있는 것" 을 고른다.
3. **배우는 자가 모두에게 되먹인다.** 거절·회귀·반려는 원장에 묻히지 않고 규칙이 되어 다음 정찰·구현·비평이 먼저 읽는다.

명부는 `agents/registry.json`, 예산은 `state/default.policy.json` 의 `budget_usd`, 역할별 켜고 끄기는 정책의 `agents` 다.

## 한 회차 (bin/run.sh round_body)

```
정찰(scout) ──brief.md──▶ 구현(builder) ──commits──▶ 러너 검증(verify/secrets/artifacts)
    ▲ ideas.json                                            │ 통과
    │                                                        ▼
    │                      ┌──── 거절(reasons) ────  비평(critic) ── 승인 ──▶ PR ──▶ CI ──▶ 머지 ──▶ 릴리즈(releaser)
    │                      ▼                             ▲
    │                 수리(repairer) ──commit──▶ 재검증 ──┘  (repair_max 번)
    │
  기록·학습(historian): campaign-lessons / operator-preferences ──▶ 정찰·구현·비평·PR 심사의 프롬프트에 주입
```

| 역할 | 파일 | 할 수 있는 것 | 만드는 것 | 누가 검사하나 |
|---|---|---|---|---|
| **정찰** scout | `agents/scout.md` | 읽기, 테스트 실행. **커밋 불가**(남긴 변경은 러너가 버림) | `brief.md`(과제·수용 기준·검증 명령·건드릴 파일·차선), `ideas.json` 재평가 | 구현자가 과제서의 근거를 코드로 확인. 맞지 않으면 차선을 고르고 원장에 이유 |
| **구현** builder | `prompt.md` | 편집·실행·커밋 | 커밋, `ledger-entry.md`, `ideas.json` | 러너 검증 → 비평가 |
| **비평** critic | `review-prompt.md` | 읽기·실행. **편집 불가** | `review.json`(verdict·reasons·risk) | `gate.py review` 가 형식 검사. 승인만 머지로 |
| **수리** repairer | `agents/repairer.md` | 편집·커밋(지적된 결함만) | 수리 커밋, `fix-summary.md` | 재검증 → 비평가가 다시 본다. 실패하면 러너가 수리 커밋을 버림 |
| **중재** arbiter | `agents/arbiter.md` | 읽기·실행. **편집 불가** | `arbiter.json`(verdict·사유별 확인/반증) | `gate.py review`. 승인이면 비평 승인과 같이 취급 |
| **릴리즈** releaser | `release-prompt.md` | 관례대로 버전·태그·자산 | `release.json`, 태그, 자산 | `gate.py release`, 자산 매니페스트, 워크플로 결과 |

- **프로젝트 프로필** `state/<프로젝트>.profile.md`: 정찰이 유지하는 저장소 요약(목적·스택·구조·검증 명령·관례·위험 구역·자주 깨지는 곳·검증 함정, 60줄 안). 없거나 14일이 지나면 정찰이 다시 쓰고, 비밀값 검사를 통과한 것만 저장된다. 구현·비평·수리·중재·PR 수리가 모두 이것부터 읽는다 — 매 회차 "파악" 에 쓰던 시간을 줄이고 모든 역할이 같은 그림을 본다.
- **중재**: 비평가가 거절했는데 수리 에이전트가 "지적이 틀렸다" 며 `fix-summary.md` 에 근거만 남기고 손대지 않았을 때만 돈다. 제3의 세션이 양쪽 주장을 읽고 코드로 확인해 판정한다. 읽기만으로 판단할 수 없는 사유는 비평가 편이다. 끄기: 정책 `agents.arbiter: false`.
- 정찰이 실패하거나 예산이 없으면 구현자가 예전처럼 직접 고른다(`stage scout failed|hold`).
- 비평·수리 루프는 **자동 머지할 변경**에만 돈다(자율화 low-risk 이상, 보호 파일 없음). 보호 파일을 건드린 변경은 사람 또는 PR 처리기가 본다.
- 수리가 `repair_max`(기본 1)번 안에 비평을 통과하지 못하면 PR 을 열고 `review held` 로 보류한다 — 그러면 PR 처리기가 한 시간 뒤 다시 잡는다.

## PR 이 열린 뒤 (bin/run.sh shepherd, 매시간)

| 역할 | 파일 | 하는 일 | 누가 검사하나 |
|---|---|---|---|
| **PR 수리** shepherd-fixer | `agents/repairer.md` (PR 브랜치 위) | CI 실패·심사 거절 사유대로 고쳐 푸시 | 러너 검증 → PR 심사 |
| **PR 심사** shepherd-reviewer | `shepherd-review-prompt.md` | 사람 대신 결정. `recommend`(merge/fix/human)를 러너가 그대로 따른다 | 승인 스윕이 CI 확인 뒤 승인 커밋에만 머지 |

## 회차 밖 (헬스체크·코파일럿)

| 역할 | 파일 | 하는 일 | 되먹임 |
|---|---|---|---|
| **기록·학습** historian | `bin/campaign-lessons.sh`, `bin/operator-prefs.sh` | 리뷰·심사 거절, 회귀, 사람 반려를 규칙으로 정제 | 정찰·구현 프롬프트, PR 심사의 HOLD_NOTE |
| **캠페인 설계** planner | `bin/campaign-draft.sh` | 목표 한 문장 → 조사·표준·대상·예산 초안 | 사람이 `activate-campaign` 으로 시작 |
| **진단** triager | `bin/ask-claude.sh` | 러너가 설명 못 하는 이상을 읽고 원인·다음 일 제안 | 사람 |
| **코파일럿** copilot | `bin/copilot.sh` + `bin/ops.sh` | 텔레그램 답장을 운영 동사로 | 사람(대화), 동사 목록이 권한 경계 |

## 어떻게 협업하나 — 회차 노트

역할들은 산출물(brief.md, review.json, fix-summary.md)만 주고받는 것이 아니라 **한 회차의 노트 한 장**(`state/runs/<run>/journal.md`)에 차례로 적는다. 다음 역할은 앞선 노트를 먼저 읽는다.

| 누가 | 무엇을 적나 | 누가 그것부터 읽나 |
|---|---|---|
| 정찰 | 왜 이 과제인가, 과제서에서 추측으로 적은 곳, 구현자가 조심할 것 | 구현 |
| 구현 | 무엇을 왜, **확신 없는 곳·검증 못 한 것**, 일부러 안 한 것, 다음 역할이 조심할 것 | 비평(확신 없는 곳부터), 수리, 릴리즈 |
| 비평 | 확인한 것·못 본 것, 승인이어도 남는 우려, 거절이면 수리가 먼저 볼 파일 | 수리, 중재, 릴리즈, PR 심사 |
| 수리 | 맞았던 지적·틀렸던 지적, 고친 방법, 여전히 확신 없는 곳 | 비평(재심), 중재 |
| 중재 | 어느 편이 왜 맞았나, 다음 비평이 배울 것 | 비평(다음 회차, `$ARBITER_HISTORY`) |
| PR 심사 | 확인한 것, 못 본 것, 권고의 근거 | 사람, 다음 심사 |
| 러너 | 단계 판정([러너] 줄): 검증·비평·수리·PR·CI·머지·릴리즈 결과 | 모두 |

노트는 PR 본문(접힌 "회차 노트")과 릴리즈 에이전트의 변경 요약에도 실리고, PR 처리기는 PR 을 연 회차의 노트를 이어받아 심사한다. 비밀값 검사를 통과한 노트만 밖으로 나간다.

되먹임 두 가지가 더 있다.
- **과제서 판정**: 구현자는 원장에 `- 과제서: 채택|차선|기각 — 이유` 를 적고, 러너가 `stage brief` 로 기록한다. 정찰은 다음 회차에 자기 과제서들이 어떻게 됐는지(`$BRIEF_HISTORY`)를 읽고 기각·차선이 반복된 유형을 피한다. 성적표가 채택률을 센다.
- **중재 이력**: 중재가 비평을 뒤집은 사례(`$ARBITER_HISTORY`)를 다음 비평이 읽어, 같은 종류의 지적은 근거를 더 확실히 한다.

## 누가 누구를 보완하나

- 정찰 ↔ 구현: 정찰은 고르기만 하니 "쉬운 것" 에 끌리지 않고, 구현은 과제서를 코드로 검증하니 정찰의 오판을 잡는다.
- 구현 ↔ 비평: 비평은 diff 만 읽고 "머지하면 안 되는 이유" 를 찾는다. 자기 코드를 스스로 승인하는 일이 없다.
- 비평 ↔ 수리: 수리는 지적된 결함만 고치고, 지적이 틀렸으면 근거를 적고 손대지 않는다. 비평가가 그 근거를 다시 읽는다.
- 회차 안 비평·수리 ↔ PR 처리기: 회차 안에서 못 푼 것은 한 시간 뒤 다른 세션이 다시 본다. 같은 세션의 고집이 이어지지 않는다.
- 기록·학습 ↔ 모두: 한 저장소에서 걸린 것이 규칙이 되어 나머지 저장소의 정찰·구현·비평이 먼저 읽는다. 사람의 반려 기준도 같은 길로 들어온다.
- 코파일럿 ↔ 사람: 사람이 봇에 말하면 동사가 되고, 그 말은 다시 운영자 취향으로 학습된다.

## 비용 (회차당 기본)

| 단계 | 예산 | 비고 |
|---|---|---|
| 정찰 | $2 | 읽기 전용, 10분 |
| 구현 | $8 (캠페인은 12~18) | |
| 비평 | $4 | 자동 머지할 때만 |
| 수리 | $6 | 비평이 거절했을 때만, 최대 repair_max 번 |
| 릴리즈 | $10 | |

| 중재 | $3 | 비평·수리가 맞설 때만 |

`state/<프로젝트>.policy.json` 에서 `budget_usd.scout/repair/arbiter`·`agents.scout`·`agents.repair_max`·`agents.arbiter` 를 덮어쓴다. 모델을 역할별로 바꾸려면 `agents/registry.json` 의 `model` 을 채운다(비면 러너 기본 `MODEL`). 적은 모델을 쓸 수 없으면(없는 모델·막힘) 러너가 기본 모델로 한 번 더 돌리므로 회차가 죽지 않는다.

## 문헌에서 가져온 것 (2026-09-19)

- **교차 모델 비평** — 정책 `agents.critic_engine: codex` 면 비평을 Claude 대신 OpenAI Codex 가 한다. 같은 계열이 만들고 판정할 때의 자기 선호 편향(Zheng et al. 2023; Wataoka et al. 2024)을 피하는 선택지. 켜기 전에 `bin/exp-cross-critic.sh` 로 두 비평가의 일치도를 잰다(결과는 `docs/paper/experiments/`).
- **머지 뒤 수정 필요율** — `bin/postmerge.py`(헬스체크, 6시간마다)가 러너가 머지한 PR 이 건드린 파일이 30일 안에 fix/revert 류 커밋으로 다시 고쳐졌는지를 세어 `docs/data/postmerge.json` 에 둔다. 에이전트 PR 이 머지 뒤 더 많은 수정 유지보수를 필요로 한다는 보고(Xia & Miller 2026)에 대한 우리 쪽 측정. 성적표에 승인 주체별·비평 위험도별로 나온다.
- **MAST 실패 분류** — 성적표가 실패를 Cemri et al. (2025) 의 세 범주(시스템 설계·인프라 / 에이전트 간 불일치 / 검증·종료)로 나눠 센다.

## 비교 실험 (state/experiment.json)

역할이 정말 효과가 있는지는 전후 비교로 말할 수 없다(시스템이 매일 바뀐다). 그래서 개선 회차마다 run_id 해시로 arm 을 무작위 배정하고, arm 의 `overrides` 가 그 회차의 정책을 덮어쓴다(기본 < 프로젝트 < arm). 진행 중인 실험 `roles-2026-09` 의 arm: baseline(가중치 2), no-scout, no-repair, no-arbiter, codex-critic, no-journal, no-lessons — 판단 역할을 하나씩 뺀다. 어떤 arm 도 검증·보호 경로·CI·승인 SHA 는 끄지 않는다. 기록은 `runs.jsonl` 의 `arm`/`experiment`, 분석은 `bin/exp-analyze.py`(헬스체크가 6시간마다 `docs/paper/experiments/ab-<id>.md` 갱신). 끝내려면 `enabled: false`. 정책 값이 `false` 인 스위치가 읽히도록 `policy()` 의 `// empty` 를 고쳤다(2026-09-19).

## 성적표

대시보드 '에이전트 성적표(최근 14일)' 와 `summary.json` 의 `agents` 에 역할별 호출 수·핵심 지표·비용이 실린다: 정찰의 과제서 작성률과 그 회차의 PR 도달률, 구현의 검증 통과율, 비평의 최종 승인률과 승인·머지 뒤 회귀, 수리의 재검증 통과율, 중재가 어느 편을 들었는지, PR 심사의 승인·거절·사람 필요와 승인 뒤 회귀, 각 역할의 비용. 지표가 어긋나면(수리 성공률 30% 미만, 비평 승인 뒤 회귀 15% 초과, 중재가 70% 넘게 수리 편 등) 무엇을 조정할지 '권장' 으로 적는다. 정책을 자동으로 바꾸지는 않는다 — 조정은 사람이 한다.

## 검증

`python3 tests/test_sim.py` 의 `Agents` 시나리오: 정찰 과제서 → 비평 1회 거절 → 수리 → 비평 승인 → 릴리즈, 비평이 계속 거절하면 PR 보류, 정찰이 남긴 변경은 버려짐, 수리가 커밋을 못 만들면 보류.

